package model;
import java.time.LocalDate;
public class Bill { private int billId,patientId; private Integer appointmentId; private double consultationFee,medicineCharges,labCharges,otherCharges,totalAmount; private String paymentStatus; private LocalDate billDate; public int getBillId(){return billId;} public void setBillId(int v){billId=v;} public int getPatientId(){return patientId;} public void setPatientId(int v){patientId=v;} public Integer getAppointmentId(){return appointmentId;} public void setAppointmentId(Integer v){appointmentId=v;} public double getConsultationFee(){return consultationFee;} public void setConsultationFee(double v){consultationFee=v;} public double getMedicineCharges(){return medicineCharges;} public void setMedicineCharges(double v){medicineCharges=v;} public double getLabCharges(){return labCharges;} public void setLabCharges(double v){labCharges=v;} public double getOtherCharges(){return otherCharges;} public void setOtherCharges(double v){otherCharges=v;} public double getTotalAmount(){return totalAmount;} public void setTotalAmount(double v){totalAmount=v;} public String getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(String v){paymentStatus=v;} public LocalDate getBillDate(){return billDate;} public void setBillDate(LocalDate v){billDate=v;} }
